INSERT INTO documents (slug, doc_citation, description, date, categories, institution, url) VALUES
  ('db-alm-protocol-131-episkin-skin-irritation-test', '{"en-us": "EURL ECVAM DB-ALM. Protocol no. 131: EpiSkin™ Skin Irritation Test 15 min - 42 hours.", "pt-br": "EURL ECVAM DB-ALM. Protocolo nº 131: EpiSkin™ Skin Irritation Test 15 min - 42 hours."}'::jsonb, '{"en-us": "DB-ALM protocol of the EpiSkin skin irritation test (reconstructed human epidermis, MTT endpoint), cited among the reference models of OECD TG 439. The model is no longer commercially available. The file states no date.", "pt-br": "Protocolo do DB-ALM do teste de irritação cutânea EpiSkin (epiderme humana reconstruída, desfecho por MTT), citado entre os modelos de referência da TG 439 da OCDE. O modelo não está mais disponível comercialmente. O arquivo não informa data."}'::jsonb, NULL, '["method_protocol"]'::jsonb, '{"en-us": "European Union Reference Laboratory for alternatives to animal testing (EURL ECVAM), DB-ALM", "pt-br": "Laboratório de Referência da União Europeia para alternativas ao uso de animais (EURL ECVAM), DB-ALM"}'::jsonb, NULL),
  ('db-alm-protocol-135-skinethic-skin-irritation-test', '{"en-us": "EURL ECVAM DB-ALM. Protocol no. 135: SkinEthic™ Skin Irritation Test.", "pt-br": "EURL ECVAM DB-ALM. Protocolo nº 135: SkinEthic™ Skin Irritation Test."}'::jsonb, '{"en-us": "DB-ALM protocol of the SkinEthic RHE skin irritation test (42 min application and 42 h post-incubation, MTT endpoint); the model is built from normal human keratinocytes in a chemically defined medium.", "pt-br": "Protocolo do DB-ALM do teste de irritação cutânea SkinEthic RHE (42 min de aplicação e 42 h de pós-incubação, desfecho por MTT); o modelo é feito de queratinócitos humanos normais em meio quimicamente definido."}'::jsonb, NULL, '["method_protocol"]'::jsonb, '{"en-us": "European Union Reference Laboratory for alternatives to animal testing (EURL ECVAM), DB-ALM", "pt-br": "Laboratório de Referência da União Europeia para alternativas ao uso de animais (EURL ECVAM), DB-ALM"}'::jsonb, NULL),
  ('db-alm-protocol-164-epiocular-eye-irritation-test', '{"en-us": "EURL ECVAM DB-ALM. Protocol no. 164: Ocular Irritation Assay for Chemicals Using EpiOcular™ EIT.", "pt-br": "EURL ECVAM DB-ALM. Protocolo nº 164: Ocular Irritation Assay for Chemicals Using EpiOcular™ EIT."}'::jsonb, '{"en-us": "DB-ALM protocol of the EpiOcular eye irritation test (reconstructed human cornea-like epithelium, MTT endpoint), a validated reference method of OECD TG 492. The model uses normal human foreskin-derived keratinocytes that are not transformed.", "pt-br": "Protocolo do DB-ALM do teste de irritação ocular EpiOcular (epitélio corneano humano reconstruído, desfecho por MTT), método de referência validado da TG 492 da OCDE. O modelo usa queratinócitos humanos normais derivados de prepúcio, não transformados."}'::jsonb, NULL, '["method_protocol"]'::jsonb, '{"en-us": "European Union Reference Laboratory for alternatives to animal testing (EURL ECVAM), DB-ALM", "pt-br": "Laboratório de Referência da União Europeia para alternativas ao uso de animais (EURL ECVAM), DB-ALM"}'::jsonb, NULL),
  ('db-alm-protocol-190-skinethic-hce-eye-irritation-test-liquid', '{"en-us": "EURL ECVAM DB-ALM. Protocol no. 190: SkinEthic™ HCE Eye Irritation Test Liquid (EITL).", "pt-br": "EURL ECVAM DB-ALM. Protocolo nº 190: SkinEthic™ HCE Eye Irritation Test Liquid (EITL)."}'::jsonb, '{"en-us": "DB-ALM protocol of the SkinEthic HCE eye irritation test for liquid and viscous chemicals, a validated reference method of OECD TG 492. The tissue comes from a transformed human corneal epithelial cell line in a chemically defined medium.", "pt-br": "Protocolo do DB-ALM do teste de irritação ocular SkinEthic HCE para líquidos e viscosos, método de referência validado da TG 492 da OCDE. O tecido vem de uma linhagem humana transformada de epitélio corneano em meio quimicamente definido."}'::jsonb, NULL, '["method_protocol"]'::jsonb, '{"en-us": "European Union Reference Laboratory for alternatives to animal testing (EURL ECVAM), DB-ALM", "pt-br": "Laboratório de Referência da União Europeia para alternativas ao uso de animais (EURL ECVAM), DB-ALM"}'::jsonb, NULL),
  ('db-alm-protocol-191-skinethic-hce-eye-irritation-test-solid', '{"en-us": "EURL ECVAM DB-ALM. Protocol no. 191: SkinEthic™ HCE Eye Irritation Test Solid (EITS).", "pt-br": "EURL ECVAM DB-ALM. Protocolo nº 191: SkinEthic™ HCE Eye Irritation Test Solid (EITS)."}'::jsonb, '{"en-us": "DB-ALM protocol of the SkinEthic HCE eye irritation test for solid chemicals, a validated reference method of OECD TG 492.", "pt-br": "Protocolo do DB-ALM do teste de irritação ocular SkinEthic HCE para sólidos, método de referência validado da TG 492 da OCDE."}'::jsonb, NULL, '["method_protocol"]'::jsonb, '{"en-us": "European Union Reference Laboratory for alternatives to animal testing (EURL ECVAM), DB-ALM", "pt-br": "Laboratório de Referência da União Europeia para alternativas ao uso de animais (EURL ECVAM), DB-ALM"}'::jsonb, NULL),
  ('db-alm-skinethic-hce-time-to-toxicity-liquids-ttl', '{"en-us": "SkinEthic™ HCE Time-to-Toxicity on Liquids SOP, Version 1 (2019) and Version 2 (June 2020). DB-ALM Protocol: In vitro eye hazard identification time-to-toxicity test method on liquids (TTL) using SkinEthic™ human corneal epithelium model (HCE).", "pt-br": "SOP SkinEthic™ HCE Time-to-Toxicity on Liquids, Versão 1 (2019) e Versão 2 (junho de 2020). Protocolo do DB-ALM: In vitro eye hazard identification time-to-toxicity test method on liquids (TTL) using SkinEthic™ human corneal epithelium model (HCE)."}'::jsonb, '{"en-us": "DB-ALM protocol (version 2, June 2020) of the SkinEthic HCE time-to-toxicity test for liquids, the SOP cited by OECD TG 492B. It classifies liquids into UN GHS No Category, Category 2 and Category 1 from three exposure times, and states that the model and its maintenance medium are proprietary to EPISKIN SA.", "pt-br": "Protocolo do DB-ALM (versão 2, junho de 2020) do teste de tempo até a toxicidade do SkinEthic HCE para líquidos, o SOP citado pela TG 492B da OCDE. Classifica líquidos em UN GHS Sem Categoria, Categoria 2 e Categoria 1 com base em três tempos de exposição, e informa que o modelo e seu meio de manutenção são proprietários da EPISKIN SA."}'::jsonb, NULL, '["method_protocol"]'::jsonb, '{"en-us": "L’Oréal Research & Innovation and EPISKIN SA, published in the EURL ECVAM DB-ALM", "pt-br": "L’Oréal Research & Innovation e EPISKIN SA, publicado no DB-ALM do EURL ECVAM"}'::jsonb, NULL),
  ('db-alm-skinethic-hce-time-to-toxicity-solids-tts', '{"en-us": "SkinEthic™ HCE Time-to-Toxicity on Solids SOP, Version 1 (June 25, 2019) and Version 2 (June 16, 2020). DB-ALM Protocol: In vitro eye hazard identification time-to-toxicity test method on solids (TTS) using SkinEthic™ human corneal epithelium model (HCE).", "pt-br": "SOP SkinEthic™ HCE Time-to-Toxicity on Solids, Versão 1 (25 de junho de 2019) e Versão 2 (16 de junho de 2020). Protocolo do DB-ALM: In vitro eye hazard identification time-to-toxicity test method on solids (TTS) using SkinEthic™ human corneal epithelium model (HCE)."}'::jsonb, '{"en-us": "DB-ALM protocol (version 2, 16 June 2020) of the SkinEthic HCE time-to-toxicity test for solids, the SOP cited by OECD TG 492B. It uses two exposure times (30 and 120 min).", "pt-br": "Protocolo do DB-ALM (versão 2, 16 de junho de 2020) do teste de tempo até a toxicidade do SkinEthic HCE para sólidos, o SOP citado pela TG 492B da OCDE. Usa dois tempos de exposição (30 e 120 min)."}'::jsonb, '2020-06-16'::date, '["method_protocol"]'::jsonb, '{"en-us": "L’Oréal Research & Innovation and EPISKIN SA, published in the EURL ECVAM DB-ALM", "pt-br": "L’Oréal Research & Innovation e EPISKIN SA, publicado no DB-ALM do EURL ECVAM"}'::jsonb, NULL),
  ('jtec-labcyte-epi-model24-skin-irritation-test-sop-v8-3', '{"en-us": "Japan Tissue Engineering Co., Ltd. (2011). In vitro skin irritation test: human epidermis model, LabCyte EPI-MODEL24. S.O.P. Skin irritation test-42 hours, Ver. 8.3 (June 2011). JSAAE skin irritation test validation study.", "pt-br": "Japan Tissue Engineering Co., Ltd. (2011). In vitro skin irritation test: human epidermis model, LabCyte EPI-MODEL24. S.O.P. Skin irritation test-42 hours, Ver. 8.3 (junho de 2011). Estudo de validação do teste de irritação cutânea da JSAAE."}'::jsonb, '{"en-us": "SOP of the LabCyte EPI-MODEL24 skin irritation test (OECD TG 439 model). States that the tissue is grown for 13 days in a medium with 5% fetal bovine serum from neonatal-foreskin keratinocytes expanded on 3T3-J2 feeder cells.", "pt-br": "SOP do teste de irritação cutânea LabCyte EPI-MODEL24 (modelo da TG 439 da OCDE). Informa que o tecido é cultivado por 13 dias em meio com 5% de soro fetal bovino, a partir de queratinócitos de prepúcio neonatal expandidos sobre células alimentadoras 3T3-J2."}'::jsonb, NULL, '["method_protocol"]'::jsonb, '{"en-us": "Japan Tissue Engineering Co., Ltd. (J-TEC) and JaCVAM", "pt-br": "Japan Tissue Engineering Co., Ltd. (J-TEC) e JaCVAM"}'::jsonb, NULL),
  ('jtec-labcyte-epi-model24-skin-corrosion-test-sop-v1-6', '{"en-us": "Japan Tissue Engineering Co., Ltd. (2017). In vitro skin corrosion test: human epidermis model, LabCyte EPI-MODEL24. S.O.P. Skin corrosion test, Version 1.6 (May 2017).", "pt-br": "Japan Tissue Engineering Co., Ltd. (2017). In vitro skin corrosion test: human epidermis model, LabCyte EPI-MODEL24. S.O.P. Skin corrosion test, Versão 1.6 (maio de 2017)."}'::jsonb, '{"en-us": "SOP of the LabCyte EPI-MODEL24 skin corrosion test. Same culture system as the irritation test: 5% fetal bovine serum and 3T3-J2 feeder cells.", "pt-br": "SOP do teste de corrosão cutânea LabCyte EPI-MODEL24. Mesmo sistema de cultura do teste de irritação: 5% de soro fetal bovino e células alimentadoras 3T3-J2."}'::jsonb, NULL, '["method_protocol"]'::jsonb, '{"en-us": "Japan Tissue Engineering Co., Ltd. (J-TEC) and JaCVAM", "pt-br": "Japan Tissue Engineering Co., Ltd. (J-TEC) e JaCVAM"}'::jsonb, NULL),
  ('jacvam-labcyte-epi-model24-skin-corrosion-peer-review-report-2018', '{"en-us": "JaCVAM Peer Review Panel (2018-10-26). Evaluation of the performance-based validation study on the LabCyte EPI-MODEL24 in vitro skin corrosion test method as a me-too test method according to OECD GD 219 and falling within the OECD TG 431.", "pt-br": "Painel de Revisão por Pares do JaCVAM (26/10/2018). Evaluation of the performance-based validation study on the LabCyte EPI-MODEL24 in vitro skin corrosion test method as a me-too test method according to OECD GD 219 and falling within the OECD TG 431."}'::jsonb, '{"en-us": "Peer review panel report on the LabCyte EPI-MODEL24 skin corrosion test as a me-too method. It documents the 5% foetal bovine serum in the production medium, the 3T3-J2 feeder cells and the serum batch checks.", "pt-br": "Relatório do painel de revisão por pares do teste de corrosão cutânea LabCyte EPI-MODEL24 como método \"me-too\". Documenta o soro fetal bovino a 5% no meio de produção, as células alimentadoras 3T3-J2 e as verificações de lote de soro."}'::jsonb, '2018-10-26'::date, '["other"]'::jsonb, '{"en-us": "Japanese Center for the Validation of Alternative Methods (JaCVAM)", "pt-br": "Centro Japonês para a Validação de Métodos Alternativos (JaCVAM)"}'::jsonb, NULL),
  ('jtec-labcyte-cornea-model24-eye-irritation-test-protocol-v2-7', '{"en-us": "Japan Tissue Engineering Co., Ltd. (2018). In vitro eye irritation test using human corneal tissue model: LabCyte CORNEA-MODEL24 eye irritation test operation protocol, Ver. 2.7 (October 2018).", "pt-br": "Japan Tissue Engineering Co., Ltd. (2018). In vitro eye irritation test using human corneal tissue model: LabCyte CORNEA-MODEL24 eye irritation test operation protocol, Ver. 2.7 (outubro de 2018)."}'::jsonb, '{"en-us": "Operation protocol of the LabCyte CORNEA-MODEL24 eye irritation test (OECD TG 492 model). The tissue comes from normal human corneal epithelial cells of a donor cornea, expanded on 3T3-J2 feeder cells and cultured in a medium with 5% fetal bovine serum.", "pt-br": "Protocolo operacional do teste de irritação ocular LabCyte CORNEA-MODEL24 (modelo da TG 492 da OCDE). O tecido vem de células epiteliais corneanas humanas normais de córnea de doador, expandidas sobre células alimentadoras 3T3-J2 e cultivadas em meio com 5% de soro fetal bovino."}'::jsonb, NULL, '["method_protocol"]'::jsonb, '{"en-us": "Japan Tissue Engineering Co., Ltd. (J-TEC) and JaCVAM", "pt-br": "Japan Tissue Engineering Co., Ltd. (J-TEC) e JaCVAM"}'::jsonb, NULL),
  ('kao-episensa-epidermal-sensitization-assay-sop-v2-6', '{"en-us": "Kao Corporation (2022-08-22). Standard operating procedure: EpiSensA, Epidermal Sensitization Assay, Version 2.6.", "pt-br": "Kao Corporation (22/08/2022). Standard operating procedure: EpiSensA, Epidermal Sensitization Assay, Versão 2.6."}'::jsonb, '{"en-us": "SOP of the EpiSensA epidermal sensitisation assay (OECD TG 442D). It uses the LabCyte EPI-MODEL24 kit from J-TEC (normal human epidermal keratinocytes) and measures four marker genes by real-time PCR.", "pt-br": "SOP do ensaio de sensibilização epidérmica EpiSensA (TG 442D da OCDE). Usa o kit LabCyte EPI-MODEL24 da J-TEC (queratinócitos epidérmicos humanos normais) e mede quatro genes marcadores por PCR em tempo real."}'::jsonb, '2022-08-22'::date, '["method_protocol"]'::jsonb, '{"en-us": "Kao Corporation and JaCVAM", "pt-br": "Kao Corporation e JaCVAM"}'::jsonb, NULL),
  ('kocvam-keraskin-phototoxicity-assay-sop-v1-3', '{"en-us": "Kang, N.H. (2025-11-26). Standard operating procedure: KeraSkin™ Phototoxicity Assay, Version 1.3. Korean Center for the Validation of Alternative Methods (KoCVAM), National Institute of Food and Drug Safety Evaluation.", "pt-br": "Kang, N.H. (26/11/2025). Standard operating procedure: KeraSkin™ Phototoxicity Assay, Versão 1.3. Centro Coreano para a Validação de Métodos Alternativos (KoCVAM), Instituto Nacional de Avaliação da Segurança de Alimentos e Medicamentos."}'::jsonb, '{"en-us": "SOP of the KeraSkin phototoxicity assay, a me-too method to the EpiDerm phototoxicity test, cited by OECD TG 498. The tissue is made of primary cultured human keratinocytes of Korean origin; the SOP does not describe the medium composition.", "pt-br": "SOP do ensaio de fototoxicidade KeraSkin, método \"me-too\" do teste de fototoxicidade EpiDerm, citado pela TG 498 da OCDE. O tecido é feito de queratinócitos humanos primários de origem coreana; o SOP não descreve a composição do meio."}'::jsonb, '2025-11-26'::date, '["method_protocol"]'::jsonb, '{"en-us": "Korean Center for the Validation of Alternative Methods (KoCVAM), National Institute of Food and Drug Safety Evaluation", "pt-br": "Centro Coreano para a Validação de Métodos Alternativos (KoCVAM), Instituto Nacional de Avaliação da Segurança de Alimentos e Medicamentos"}'::jsonb, NULL),
  ('biosolution-mctt-hce-eye-irritation-test-sop-v1-8', '{"en-us": "Biosolution Co., Ltd. (2024-01-22). In vitro eye irritation test with a reconstructed human cornea-like epithelium test method, MCTT HCE™. SOP Version 1.8.", "pt-br": "Biosolution Co., Ltd. (22/01/2024). In vitro eye irritation test with a reconstructed human cornea-like epithelium test method, MCTT HCE™. SOP Versão 1.8."}'::jsonb, '{"en-us": "SOP of the MCTT HCE eye irritation test (OECD TG 492 model), in Korean. The tissue is made of normal human corneal epithelial cells; the SOP does not describe the medium composition or mention serum.", "pt-br": "SOP do teste de irritação ocular MCTT HCE (modelo da TG 492 da OCDE), em coreano. O tecido é feito de células epiteliais corneanas humanas normais; o SOP não descreve a composição do meio nem cita soro."}'::jsonb, '2024-01-22'::date, '["method_protocol"]'::jsonb, '{"en-us": "Biosolution Co., Ltd. (Korea), with KoCVAM", "pt-br": "Biosolution Co., Ltd. (Coreia), com o KoCVAM"}'::jsonb, NULL);
